using BladeControl.Core.Models;

namespace BladeControl.Core.Hardware;

/// <summary>
/// Every Razer laptop this app knows how to find. To add one: plug it in with
/// nothing else Razer-branded attached, open Device Manager, find the
/// keyboard-adjacent HID device under this vendor, and read the product id
/// (the four hex digits after "PID_") from its Hardware Ids. It is safe to
/// add an unverified entry; see <see cref="RazerLaptopModel.Verified"/>.
/// </summary>
internal static class RazerLaptopModels
{
    public static readonly IReadOnlyList<RazerLaptopModel> Known =
    [
        new RazerLaptopModel(0x029F, "Razer Blade 16 (2023)", Verified: true),

        // Community-reported product ids, not verified on this app: the
        // command set is the one documented for the Blade 16 (2023) above,
        // tried the same way on these (see RazerCommands). A command the
        // firmware does not implement fails cleanly rather than guessing.
        // From sqmagellan/razer-ctl's published device-support table.
        new RazerLaptopModel(0x028A, "Razer Blade 15 (2022)", Verified: false),
        new RazerLaptopModel(0x029D, "Razer Blade 14 (2023) Mercury", Verified: false),
        new RazerLaptopModel(0x02B7, "Razer Blade 16 (2024)", Verified: false),
        new RazerLaptopModel(0x02C6, "Razer Blade 16 (2025)", Verified: false, MayHaveBatteryModes: true),

        // The other Blades from 2021 on, by the product ids OpenRazer's
        // keyboard driver lists for them. Same command set, same caveat: not
        // verified here, and what a firmware lacks is refused cleanly.
        new RazerLaptopModel(0x026D, "Razer Blade 15 Advanced (Early 2021)", Verified: false),
        new RazerLaptopModel(0x026E, "Razer Blade 17 Pro (Early 2021)", Verified: false),
        new RazerLaptopModel(0x026F, "Razer Blade 15 Base (Early 2021)", Verified: false),
        new RazerLaptopModel(0x0270, "Razer Blade 14 (2021)", Verified: false),
        new RazerLaptopModel(0x0276, "Razer Blade 15 Advanced (Mid 2021)", Verified: false),
        new RazerLaptopModel(0x0279, "Razer Blade 17 Pro (Mid 2021)", Verified: false),
        new RazerLaptopModel(0x027A, "Razer Blade 15 Base (2022)", Verified: false),
        new RazerLaptopModel(0x028B, "Razer Blade 17 (2022)", Verified: false),
        new RazerLaptopModel(0x028C, "Razer Blade 14 (2022)", Verified: false),
        new RazerLaptopModel(0x029E, "Razer Blade 15 (2023)", Verified: false),
        new RazerLaptopModel(0x02A0, "Razer Blade 18 (2023)", Verified: false),
        new RazerLaptopModel(0x02B6, "Razer Blade 14 (2024)", Verified: false),
        new RazerLaptopModel(0x02B8, "Razer Blade 18 (2024)", Verified: false),
        new RazerLaptopModel(0x02C5, "Razer Blade 14 (2025)", Verified: true, MayHaveBatteryModes: true), // Confirmed by a user on their own.
        new RazerLaptopModel(0x02C7, "Razer Blade 18 (2025)", Verified: false, MayHaveBatteryModes: true),
        new RazerLaptopModel(0x02E0, "Razer Blade 16 (2026)", Verified: false, MayHaveBatteryModes: true),
        new RazerLaptopModel(0x02E1, "Razer Blade 18 (2026)", Verified: false, MayHaveBatteryModes: true),

        // Tested by a user on their own RZ09-0328: performance modes (Gaming
        // included), Custom boost levels, lighting (its keyboard is a single
        // zone, so no Wave) and the controller temperature work. Its firmware
        // echoes every class 0x07
        // read and write without acting on it, so the charge limit and the
        // max fan flag only look accepted; max fan speed works through the
        // older manual fan method instead (not in Silent). It has no fan speed
        // command (0x0D88).
        new RazerLaptopModel(
            0x0255,
            "Razer Blade 15 Base (2020)",
            Verified: false,
            HasChargeLimit: false,
            MaxFan: MaxFanMethod.ManualFan,
            HasKeyboardColor: true,
            HasFanSpeeds: false,
            HasWaveEffect: false),
    ];
}

namespace BladeControl.Core.Models;

/// <summary>
/// Performance modes Razer Synapse offers on the Blade 16 (2023), plus the
/// 2020 Blades' Gaming, which the laptop may still report but the app no
/// longer offers. The values are the EC's wire
/// bytes. The 2025 and later firmware's battery modes (Battery Saver 3,
/// Battery Balanced 6) are sent and read as Silent and Balanced on battery
/// (see <see cref="Services.PerformanceService"/>); Hyperboost is left out.
/// </summary>
internal enum PerformanceMode : byte
{
    Balanced = 0,

    // The 2020 Blades' high-performance mode (Synapse called it Gaming).
    // Not offered any more: a saved Gaming profile is applied as Balanced.
    Gaming = 1,

    Custom = 4,
    Silent = 5
}

}

      var state = ReadState();

      // Report what the EC says rather than what was asked for.
      if (state.MaxFan != enabled)
          AppLog.Error($"The EC accepted max fan speed {(enabled ? "on" : "off")} but reports {state.MaxFan?.ToString() ?? "unknown"}.");

      return state;
  }

  private void SetMaxFanFlag(bool enabled)
  {
      // The EC rejects this command outside Custom, so it is never sent from
      // any other mode, whatever the caller believes the mode is.
      if (GetMode() != PerformanceMode.Custom)
          throw new InvalidOperationException("Max fan speed can only be changed in Custom mode.");

      transport.SendAndConfirm(
          RazerCommands.SetMaxFan,
          [enabled ? MaxFanOn : MaxFanOff],
          $"max fan speed {(enabled ? "on" : "off")}");
  }

  // Each fan is switched to manual (or back to automatic) by rewriting the
  // current mode with the fan byte set, then given its fixed speed. The mode
  // itself is left as it is.
  private void SetManualFan(bool enabled)
  {
      // Silent holds the fans down whatever is asked, so Max would only look
      // on there. Turning it off is allowed in any known mode.
      if (GetMode() is not PerformanceMode mode || (enabled && mode == PerformanceMode.Silent))
          throw new InvalidOperationException("Max fan speed is not available in this mode.");

      // The byte the EC holds, so a battery mode is rewritten as itself.
      var wire = _lastWireMode ?? (byte)mode;

      foreach (var zone in Zones)
      {
          transport.SendAndConfirm(
              RazerCommands.SetPerformanceMode,
              [0x01, zone, wire, enabled ? FanModeManual : FanModeAuto],
              $"fan mode {(enabled ? "manual" : "automatic")} for zone {zone}");

          if (enabled)
          {
              transport.SendAndConfirm(
                  RazerCommands.SetFanRpm,
                  [0x01, zone, ManualMaxRpmHundreds],
                  $"fan speed for zone {zone}");
          }
      }
  }

  // Both fans manual means Max is on, both automatic that it is off.
  private bool? ReadManualFan()
  {
      var cpu = ReadZoneFanMode(Zones[0]);
      var gpu = ReadZoneFanMode(Zones[1]);

      return cpu == gpu
          ? cpu switch
          {
              FanModeManual => true,
              FanModeAuto => false,
              _ => null
          }
          : null;
  }

  private byte ReadZoneFanMode(byte zone) =>
      RazerHidPacket.GetArgument(transport.Send(RazerCommands.GetPerformanceMode, [0x00, zone, 0x00, 0x00]), 3);

